using Confluent.Kafka;using Medzo.CatalogueInventory.Application.Common;using Medzo.CatalogueInventory.Infrastructure.Messaging;using Medzo.CatalogueInventory.Infrastructure.Persistence;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Configuration;using Microsoft.Extensions.DependencyInjection;
namespace Medzo.CatalogueInventory.Infrastructure;
public static class DependencyInjection{public static IServiceCollection AddInfrastructure(this IServiceCollection s,IConfiguration c){var cs=c.GetConnectionString("CatalogueInventory");if(string.IsNullOrWhiteSpace(cs))throw new InvalidOperationException("Set ConnectionStrings__CatalogueInventory for the medzo_inventory_db Azure SQL database.");s.AddDbContext<CatalogueInventoryDbContext>(o=>o.UseSqlServer(cs,b=>{b.MigrationsAssembly(typeof(CatalogueInventoryDbContext).Assembly.FullName);b.EnableRetryOnFailure(5,TimeSpan.FromSeconds(10),null);}));s.AddScoped<ICatalogueInventoryStore>(x=>x.GetRequiredService<CatalogueInventoryDbContext>());var brokers=c["Kafka:BootstrapServers"]??"localhost:9092";s.AddSingleton<IProducer<string,string>>(_=>new ProducerBuilder<string,string>(new ProducerConfig{BootstrapServers=brokers,EnableIdempotence=true,Acks=Acks.All}).Build());s.AddHostedService<OutboxPublisher>();s.AddHostedService<StockEventConsumer>();return s;}}

